// Pure filtering logic for the activity page. Loaded as a plain script in the
// browser (window.ActivityFilters) and required by the Node tests.
(function (root) {
  const SECURITY_CHANGES = ['Password changed', 'Two-factor enabled', 'Email change requested'];

  // Named groups over the API's fixed event types. They only combine
  // existing types; they never introduce new ones.
  const GROUPS = {
    all: null,
    failed: ['Sign-in failed'],
    security: SECURITY_CHANGES,
    'failed-security': ['Sign-in failed', ...SECURITY_CHANGES],
  };

  function matchesGroup(event, group) {
    const types = GROUPS[group];
    return !types || types.includes(event.type);
  }

  // Local midnight on the first day of the week containing `date`, in the
  // viewer's time zone. `firstDay` follows Intl week info: 1 is Monday, 7 is Sunday.
  function weekStart(date, firstDay) {
    const offset = (date.getDay() - (firstDay % 7) + 7) % 7;
    return new Date(date.getFullYear(), date.getMonth(), date.getDate() - offset);
  }

  // Adding days through the Date constructor keeps local midnight across DST changes.
  function addDays(date, days) {
    return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
  }

  // Every week from the newest event back to the oldest, newest first.
  function listWeeks(events, firstDay) {
    if (events.length === 0) return [];
    const times = events.map((event) => new Date(event.when).getTime());
    const oldest = weekStart(new Date(Math.min(...times)), firstDay);
    const weeks = [];
    for (let week = weekStart(new Date(Math.max(...times)), firstDay); week >= oldest; week = addDays(week, -7)) {
      weeks.push(week);
    }
    return weeks;
  }

  // `week` is the start of a week from listWeeks as a timestamp, or null for every week.
  function filterEvents(events, { group, week }) {
    const end = week === null ? null : addDays(new Date(week), 7).getTime();
    return events.filter((event) => {
      if (!matchesGroup(event, group)) return false;
      if (week === null) return true;
      const time = new Date(event.when).getTime();
      return time >= week && time < end;
    });
  }

  const api = { GROUPS, matchesGroup, weekStart, listWeeks, filterEvents };
  if (typeof module === 'object' && module.exports) module.exports = api;
  else root.ActivityFilters = api;
})(this);

// Renders the events as table rows, in API order, narrowed by the filters.
const { listWeeks, filterEvents, addDays } = window.ActivityFilters;
const events = window.ACTIVITY_EVENTS;
const tbody = document.querySelector('#activity-table tbody');
const form = document.querySelector('#activity-filters');
const groupSelect = document.querySelector('#filter-group');
const weekSelect = document.querySelector('#filter-week');
const status = document.querySelector('#filter-status');

// First day of the week for the viewer's locale (1 is Monday, 7 is Sunday).
// Browsers without Intl week info fall back to Monday.
function localeFirstDay() {
  try {
    const locale = new Intl.Locale(navigator.language);
    const info = locale.getWeekInfo ? locale.getWeekInfo() : locale.weekInfo;
    return (info && info.firstDay) || 1;
  } catch {
    return 1;
  }
}

function renderRows(rows) {
  tbody.replaceChildren();
  if (rows.length === 0) {
    const row = document.createElement('tr');
    const cell = document.createElement('td');
    cell.colSpan = 6;
    cell.textContent = 'No events match these filters.';
    row.appendChild(cell);
    tbody.appendChild(row);
    return;
  }
  for (const event of rows) {
    const row = document.createElement('tr');
    for (const value of [
      new Date(event.when).toLocaleString(),
      event.type,
      event.device,
      event.location,
      event.ip,
      event.detail,
    ]) {
      const cell = document.createElement('td');
      cell.textContent = value;
      row.appendChild(cell);
    }
    tbody.appendChild(row);
  }
}

function update() {
  const week = weekSelect.value === '' ? null : Number(weekSelect.value);
  const rows = filterEvents(events, { group: groupSelect.value, week });
  renderRows(rows);
  status.textContent = `Showing ${rows.length.toLocaleString()} of ${events.length.toLocaleString()} events`;
}

const weekFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' });
for (const week of listWeeks(events, localeFirstDay())) {
  const option = document.createElement('option');
  option.value = String(week.getTime());
  option.textContent = weekFormat.formatRange(week, addDays(week, 6));
  weekSelect.appendChild(option);
}

form.addEventListener('submit', (submitEvent) => submitEvent.preventDefault());
groupSelect.addEventListener('change', update);
weekSelect.addEventListener('change', update);
form.hidden = false;
update();

